use std::{fs::{self,OpenOptions},path::{Path,PathBuf},process::{Command,Stdio},time::{Instant,Duration}};
fn run(exe:&Path,args:&[PathBuf],cwd:&Path,label:&str,setup:&Path)->bool{let open=|ext|OpenOptions::new().write(true).create_new(true).open(cwd.join(format!("{label}.{ext}"))).unwrap();let mut c=Command::new(exe).args(args).current_dir(cwd).env("HEC_SETUP_DIR",setup).stdout(Stdio::from(open("stdout"))).stderr(Stdio::from(open("stderr"))).spawn().unwrap();let t=Instant::now();loop{if let Some(s)=c.try_wait().unwrap(){fs::write(cwd.join(format!("{label}.status")),format!("exit={:?}\n",s.code())).unwrap();return s.success()}if t.elapsed().as_secs()>=300{c.kill().unwrap();c.wait().unwrap();fs::write(cwd.join(format!("{label}.status")),"censored300s\n").unwrap();return false}std::thread::sleep(Duration::from_millis(10));}}
fn solve(repo:&Path,inv:&Path,label:&str,input:&str,output:&str,cwd:&Path,setup:&Path,verify:&Path,expect:bool){let solver=repo.join("research/hec_fiberalign13_20261115/tmp/msolve/msolve");let dst=inv.join(output);let args=["-t","2","-v","1","-c","0","-f"].map(PathBuf::from).into_iter().chain([inv.join(input),PathBuf::from("-o"),dst.clone()]).collect::<Vec<_>>();assert_eq!(run(&solver,&args,cwd,&format!("solver-{label}"),setup),expect,"solver_status {label}");if expect{assert!(run(verify,&[inv.join(input),dst,PathBuf::from("-")],cwd,&format!("verify-{label}"),setup));}}
fn worker(repo:&Path,cell:&Path,arm:&str){let setup=repo.join("research/hec_calibration631_20261115");fs::create_dir(cell).unwrap();let cwd=cell.join("work");fs::create_dir(&cwd).unwrap();for d in ["hec_calibration631_20261115","hec_inputcoords631_20261116"]{std::os::unix::fs::symlink(repo.join("research").join(d),cell.join(d)).unwrap();}let direct=arm=="direct";assert!(direct||arm=="ordered");let inv=cell.join(if direct{"hec_directsymmetric631_20261116"}else{"hec_inverse631_20261116"});fs::create_dir(&inv).unwrap();let bind=Path::new("/Volumes/SSD990-2");let gen=bind.join(if direct{"hec-directsymmetric631-target/release/directsymmetric631"}else{"hec-inverse631-target/release/generate631"});let verify=bind.join(if direct{"hec-directsymmetric631-target/release/verify-direct631"}else{"hec-inverse631-target/release/verify631"});let recover=bind.join(if direct{"hec-directreplay631-target/release/directreplay631"}else{"hec-recover631-target/release/recover631"});let t=Instant::now();for label in ["D1","B"]{assert!(run(&gen,&[inv.join(format!("generated-{label}")),repo.join(format!("research/hec_inputcoords631_20261116/coordinates/{label}-KUMMER.txt"))],&cwd,&format!("generate-{label}"),&setup));let default_output=if direct&&label=="B"{"job-B.res"}else if label=="B"{"failed-B.res"}else{"solve-D1.res"};solve(repo,&inv,label,&format!("generated-{label}/target.ms"),default_output,&cwd,&setup,&verify,direct||label!="B");if !direct&&label=="B"{let source=fs::read_to_string(inv.join("generated-B/target.ms")).unwrap();let mut lines:Vec<_>=source.lines().map(str::to_string).collect();assert!(lines.last().unwrap().starts_with("1*t+"));*lines.last_mut().unwrap()="1*t+599*y3+615*x3+623*y2+627*x2+629*y1+630*x1".into();fs::create_dir(inv.join("generated-B-alt")).unwrap();fs::write(inv.join("generated-B-alt/target.ms"),lines.join("\n")+"\n").unwrap();solve(repo,&inv,"B-alt","generated-B-alt/target.ms","solve-B-alt.res",&cwd,&setup,&verify,true);}}assert!(run(&recover,&[],&cwd,"reconstruct",&setup));for label in ["D1","B"]{assert_eq!(fs::read(cwd.join(format!("class-{label}.txt"))).unwrap(),fs::read(repo.join(format!("research/hec_recover631_20261116/class-{label}.txt"))).unwrap(),"class_equivalence");}println!("MEASURE arm={arm} component_ns={} classes_verified=2",t.elapsed().as_nanos());}
fn main(){let a:Vec<_>=std::env::args().collect();if a[1]=="worker"{worker(Path::new(&a[2]),Path::new(&a[3]),&a[4]);return}assert_eq!(a.len(),4);assert_eq!(a[1],"collect");let repo=fs::canonicalize(&a[2]).unwrap();let root=PathBuf::from(&a[3]);assert!(!root.exists());fs::create_dir(&root).unwrap();let root=fs::canonicalize(root).unwrap();let mut table=String::from("block\tarm\texit\tprocess_ns\tcomponent_ns\n");for block in 0..5{for arm in if block%2==0{["ordered","direct"]}else{["direct","ordered"]}{let cell=root.join(format!("{block}-{arm}"));let t=Instant::now();let o=Command::new(std::env::current_exe().unwrap()).args(["worker",repo.to_str().unwrap(),cell.to_str().unwrap(),arm]).output().unwrap();let wall=t.elapsed().as_nanos();fs::write(root.join(format!("{block}-{arm}.stdout")),&o.stdout).unwrap();fs::write(root.join(format!("{block}-{arm}.stderr")),&o.stderr).unwrap();let s=String::from_utf8(o.stdout).unwrap();let ns=s.lines().find(|s|s.starts_with("MEASURE ")).and_then(|s|s.split_whitespace().find_map(|s|s.strip_prefix("component_ns="))).unwrap_or("NA");table.push_str(&format!("{block}\t{arm}\t{}\t{wall}\t{ns}\n",o.status.code().unwrap_or(-1)));fs::write(root.join("cells.tsv"),&table).unwrap();}}println!("{table}");}
